std::array<char, 65536> g_log_data{};
std::size_t g_log_size = 0;

void append_memory(const char *data, std::size_t size) noexcept
{
    if (g_log_size >= g_log_data.size() - 1)
        return;
    const std::size_t available = g_log_data.size() - 1 - g_log_size;
    if (size > available)
        size = available;
    std::memcpy(g_log_data.data() + g_log_size, data, size);
    g_log_size += size;
    g_log_data[g_log_size] = '\0';
}

