constexpr char kKlogPrefix[] = "[PS5VK] ";

// Mirror each JSON line to the kernel log. The HTTP buffer and log file are
// lost or truncated when the process or GPU faults; klog keeps the last
// records next to the system crash report.
void append_klog(const char *data, std::size_t size) noexcept
{
    constexpr std::size_t prefix = sizeof(kKlogPrefix) - 1;
    char line[1100]{};
    if (size > sizeof(line) - prefix - 2)
        size = sizeof(line) - prefix - 2;
    std::memcpy(line, kKlogPrefix, prefix);
    std::memcpy(line + prefix, data, size);
    std::size_t end = prefix + size;
    if (size == 0 || line[end - 1] != '\n')
        line[end++] = '\n';
    line[end] = '\0';
    (void)sceKernelDebugOutText(0, line);
}

