// One quarter of the target against one texel: every pixel of the quarter's
// middle box must hold three signals, within the 8-bit target's own rounding:
//
// - red, the quarter's own element's first component (the fetch at the
//   fragment's index),
// - green, element 0's first component, fetched with a constant index, which is
//   what tells a wrong index apart from a fetch that returns nothing, and
// - blue, the 0.25 the shader writes whatever the fetch returns, which is what
//   proves the frame drew at all.
//
// The three together are why a failing row names its failure instead of just
// reading zero: a black quarter with blue 0x40 is a fetch that returned nothing,
// one with a right blue and a red of the first level everywhere is an index the
// shader computed wrongly, and an all-zero quarter is a frame that drew nothing.
bool check_texel_buffer_frame(const void *target, const TexelBufferFormat &row, const char *label,
                              JsonLog &log) noexcept
{
    const auto *const words = static_cast<const std::uint32_t *>(target);
    const FramebufferView view{words, kTiledRgba8Layout};
    const std::uint32_t quarter = kOutputWidth / kTexelBufferTexels;
    const std::uint32_t box_width = 120;
    const std::uint32_t box_height = 80;
    constexpr std::uint8_t kConstant = 0x40; // 0.25 of 255, within the target's rounding
    std::uint32_t matched = 0;
    std::uint32_t total = 0;
    std::uint32_t quarter_matched[kTexelBufferTexels] = {};
    const auto close = [](std::uint8_t got, std::uint8_t want)
    { return got + 1 >= want && want + 1 >= got; };
    for (std::uint32_t index = 0; index < kTexelBufferTexels; ++index)
    {
        const std::uint8_t level = kTexelBufferLevels[index];
        const std::uint32_t left = quarter * index + quarter / 2 - box_width / 2;
        const std::uint32_t top = kOutputHeight / 2 - box_height / 2;
        for (std::uint32_t y = top; y < top + box_height; ++y)
            for (std::uint32_t x = left; x < left + box_width; ++x)
            {
                const std::uint32_t pixel = view.word(x, y);
                const bool same =
                    close((std::uint8_t)(pixel & 0xffu), level) &&
                    close((std::uint8_t)((pixel >> 8) & 0xffu), kTexelBufferLevels[0]) &&
                    close((std::uint8_t)((pixel >> 16) & 0xffu), kConstant);
                quarter_matched[index] += same ? 1u : 0u;
                matched += same ? 1u : 0u;
                ++total;
            }
    }
    const std::uint32_t per_quarter = box_width * box_height;
    log.number("agc_texel_buffer_fetch", "matched", matched);
    log.number("agc_texel_buffer_fetch", "of", total);
    log.number("agc_texel_buffer_fetch", "format_channels", row.channels);
    log.number("agc_texel_buffer_fetch", "format_bytes", row.texel_bytes);
    for (std::uint32_t index = 0; index < kTexelBufferTexels; ++index)
    {
        const std::uint32_t left = quarter * index + quarter / 2 - box_width / 2;
        /* What the quarter's own middle pixel holds, one field per channel:
         * which quarter is wrong and how is what a failure here needs to
         * name. */
        const std::uint32_t middle = view.word(left + box_width / 2, kOutputHeight / 2);
        log.number("agc_texel_buffer_fetch", "quarter_matched", quarter_matched[index]);
        log.number("agc_texel_buffer_fetch", "quarter_of", per_quarter);
        log.number("agc_texel_buffer_fetch", "quarter_middle_red", middle & 0xffu);
        log.number("agc_texel_buffer_fetch", "quarter_middle_green", (middle >> 8) & 0xffu);
        log.number("agc_texel_buffer_fetch", "quarter_middle_blue", (middle >> 16) & 0xffu);
        log.number("agc_texel_buffer_fetch", "quarter_middle_alpha", (middle >> 24) & 0xffu);
        log.number("agc_texel_buffer_fetch", "quarter_level", kTexelBufferLevels[index]);
    }
    log.event("agc_texel_buffer_fetch", matched == total ? "PASS" : "FAIL",
              matched == total ? 0 : -1, label);
    return matched == total;
}

void run_texel_buffer_frames(const TestContext &test, TestOutcome &outcome, const char *const event,
                             const TexelBufferFormat *const table, std::size_t count) noexcept
{
    JsonLog &log = test.log;
    const ps5vk_triangle_report report{&log, log_vulkan_step};
    unsigned fetched = 0;
    for (std::size_t index = 0; index < count; ++index)
    {
        const TexelBufferFormat &row = table[index];
        std::vector<std::uint8_t> texels((std::size_t)kTexelBufferTexels * row.texel_bytes);
        fill_texel_buffer(row, texels.data());
        ps5vk_triangle_input input{};
        input.get_instance_proc_addr = vk_icdGetInstanceProcAddr;
        input.pipeline_count = 1;
        input.load_op = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
        input.report = &report;
        input.output = PS5VK_TRIANGLE_OUTPUT_IMAGE;
        input.texel_buffer_data = texels.data();
        input.texel_buffer_bytes = (std::uint32_t)texels.size();
        input.texel_buffer_format = row.format;
        input.texel_buffer_whole_size = true;
        if (!load_vulkan_shaders(test.packages, &g_vulkan_spirv[0], input.shaders[0], log))
            return;
        ps5vk_triangle triangle{};
        ps5vk_triangle_status status = ps5vk_triangle_create(&triangle, &input);
        if (status == PS5VK_TRIANGLE_OK)
            status = ps5vk_triangle_draw(&triangle, PS5VK_TRIANGLE_ONE_DRAW);
        if (status == PS5VK_TRIANGLE_OK && test.capture)
        {
            log_driver_submission(triangle.device, "texel buffer", log);
            // One frame and one device per format: as many pipelines, and a PC
            // rebuild replays one captured stage image per pipeline it creates
            // (driver/ps5vk_pipeline.c).
            log_driver_stages(triangle.device, log);
        }
        // The V# the draw wrote, word for word, out of the table chunk the
        // stage's user data names: what the fetch reads is not otherwise in a
        // frame's evidence, and a wrong word there fetches nothing at all
        // (docs/M5_PHASE_C.md, blocker round 5).
        if (status == PS5VK_TRIANGLE_OK)
        {
            constexpr std::uint32_t kMaxChunks = 4;
            ps5vk_debug_stage chunks[kMaxChunks]{};
            const std::uint32_t chunk_count =
                ps5vk_debug_table_chunks(triangle.device, chunks, kMaxChunks);
            log.number("agc_texel_buffer_table", "chunks", chunk_count);
            if (chunk_count > 0 && chunks[0].address != nullptr)
            {
                const auto *const words = static_cast<const std::uint32_t *>(chunks[0].address);
                const std::size_t count = std::min<std::size_t>(chunks[0].bytes / 4, 8);
                for (std::size_t word = 0; word < count; ++word)
                    log.hex("agc_texel_buffer_table", "word", words[word]);
            }
        }
        char label[128]{};
        std::snprintf(label, sizeof(label),
                      "format %u fetched the texels %02x %02x %02x %02x of its buffer view",
                      (unsigned)row.format, kTexelBufferLevels[0], kTexelBufferLevels[1],
                      kTexelBufferLevels[2], kTexelBufferLevels[3]);
        log.number("agc_texel_buffer_entry", "format", (int)row.format);
        if (status == PS5VK_TRIANGLE_OK && triangle.target_bytes >= kFramebufferBytes &&
            check_texel_buffer_frame(triangle.target, row, label, log))
            ++fetched;
        if (status == PS5VK_TRIANGLE_IN_FLIGHT)
        {
            outcome.stage_in_use = true;
            log.event(event, "FAIL", -1,
                      "a submission did not complete; the program's objects stay allocated");
            return;
        }
        ps5vk_triangle_finish(&triangle);
        if (status == PS5VK_TRIANGLE_FAILED)
        {
            log.event(event, "FAIL", -1, "a format's frame could not be recorded or submitted");
            outcome.command_built = false;
            return;
        }
    }
    outcome.command_built = true;
    outcome.passed = fetched == count;
    char detail[160]{};
    std::snprintf(detail, sizeof(detail),
                  "%u of %zu uniform texel buffers fetched the four levels their view holds",
                  fetched, count);
    log.event(event, outcome.passed ? "PASS" : "FAIL", outcome.passed ? 0 : -1, detail);
}

void run_vulkan_texel_buffer_frames(const TestContext &test, TestOutcome &outcome) noexcept
{
    const std::array<TexelBufferFormat, 17> formats = texel_buffer_float_formats();
    run_texel_buffer_frames(test, outcome, "agc_v0_formats_texel_buffer", formats.data(),
                            formats.size());
}

